const envelope = $json;
if (!envelope || envelope.type !== 'fan.session_requested' || envelope.version !== 1) throw new Error('Unsupported CrowdRelay event');
const data = envelope.data ?? {};
for (const key of ['email', 'session_recovery_token']) {
  if (data[key] === undefined || data[key] === null || data[key] === '') throw new Error(`Missing recovery field: ${key}`);
}
const base = ("https://virya.music" || '').replace(/\/$/, '');
if (!base) throw new Error('Missing CROWDRELAY_PUBLIC_SITE_URL');
const token = String(data.session_recovery_token).trim();
const encodedToken = encodeURIComponent(token);
const confirmationUrl = `${base}/signal/confirm#token=${encodedToken}`;
const confirmationDeepLink = `virya-signal://fan/confirm?token=${encodedToken}`;
return [{ json: { event_id: envelope.id, mail: {
  template: 'crowdrelay-confirm-email', to: data.email,
  variables: {
    display_name: data.display_name ?? null,
    locale: data.locale ?? 'pl-PL',
    purpose: 'session_recovery',
    confirmation_url: confirmationUrl,
    confirmation_token: token,
    confirmation_deep_link: confirmationDeepLink,
    confirmation_qr_payload: confirmationDeepLink,
    policy_version: data.policy_version ?? null
  },
  idempotency_key: envelope.id
} } }];
